import re
from abc import ABC, abstractmethod
from copy import deepcopy
from ipaddress import IPv4Address
from itertools import count


class Config:

    @classmethod
    def get_config(cls, basic_config, bts_id_arg, rmods, bbmods_smods):
        """Entry point for generator. Iterates over every top-level key in enb|gnb|vcu yaml and calls
        corresponding generator. For the time being GNB and ENB have the same generator, as there are almosto
        no differences.

        Only two additional keys are added by this class -> "num" and "id", as they rely on internal functions.
        """

        CONFIGURATORS = {
            "ENB": BTSConfigurator,
            "GNB": BTSConfigurator,
            "VCU": VCUConfigurator,
        }

        bts_id_map = cls.parse_bts_id_arg(bts_id_arg)

        ret_config = {}
        for bts_key, bts_ent in basic_config.items():
            bts_type, bts_num = cls.unparse_bts_key(bts_key)
            bts_id = bts_id_map[bts_key] if bts_key in bts_id_map else bts_num

            configurator = CONFIGURATORS[bts_type.upper()]
            configurator().get_config(bts_ent, rmods, bbmods_smods)
            bts_ent["num"] = bts_num
            bts_ent["id"] = bts_id
            ret_config[bts_key] = bts_ent

        return ret_config

    @staticmethod
    def parse_bts_id_arg(bts_id_arg):
        """
        Creates dict which maps main key with the one provided by the user with --bts_id arg.
        E.g. --bts_id enb1=300034
        """
        bts_map = {}

        if not bts_id_arg:
            return bts_map

        for bts_ids in bts_id_arg.split(":"):
            bts_key, bts_id = bts_ids.split("=")
            bts_map[bts_key] = bts_id

        return bts_map

    @staticmethod
    def unparse_bts_key(bts_key):
        """
        Returns type and declared id.
        E.g. enb1 -> ('enb', '1')
        """
        match = re.match(r"(gnb|vcu|enb)(\d+)$", bts_key, re.IGNORECASE)
        if match:
            return match.group(1, 2)
        raise Exception("Wrong BTS key: {bts_key}")


class Configurator(ABC):

    @abstractmethod
    def get_config(self, bts_ent):
        pass

    def get_cells_count_fdd(self, cells):
        return len([cell_ent for cell_ent in cells.values() if self.is_cell_ent_fdd(cell_ent)])

    def get_cells_count_tdd(self, cells):
        return len(cells) - self.get_cells_count_fdd(cells)

    @staticmethod
    def is_ecpri(radios):
        return any(radio.get("protocol_type") == "eCPRI" for radio in radios.values())

    @staticmethod
    def is_oran(radios):
        return any(radio.get("type") == "ORAN" for radio in radios.values())

    @staticmethod
    def is_cell_ent_fdd(cell_ent):
        if "earfcn_dl" in cell_ent:
            return True
        return False


class BTSConfigurator(Configurator):

    def get_config(self, bts_ent, rmods, bbmods_smods):

        BTSConfiguratorExpander().expand_config(bts_ent)
        sync = bts_ent.get("sync", "")
        enb_ent_config = {
            "cells_count": len(bts_ent["cells"]),
            "radios_count": len(bts_ent["radios"]),
            "smods_count": self.get_smods_count(bts_ent),
            "bbpool_count": self.get_bbpool_count(bts_ent),
            "bbmods_count": self.get_bbmods_count(bts_ent),
            "is_ipv4": "enb_ip" in bts_ent,
            "is_ipv6": "enb_ipv6_prefix_length" in bts_ent and "enb_ipv6" in bts_ent,
            "is_ipv6_mplane": bts_ent.get("ipv6_for_mplane", "") == "true",
            "is_ipv6_s1x2": bts_ent.get("ipv6_for_s1x2", "") == "true",
            "is_ipv6_splane": bts_ent.get("ipv6_for_splane", "") == "true",
            "enb_ip_prefix_length": bts_ent.get("enb_ip_prefix_length", "24"),
            "mnc_length": "3" if len(bts_ent["mnc"]) > 2 else "2",
            "is_validate_sync": sync in ("gps", "gpsf", "topf", "topp", "hub"),
            "has_freq_sync": sync == "topf" or sync == "gpsf",
            "has_hub_sync": sync.startswith("hub"),
            "has_top_sync": sync.startswith("top"),
            "has_gps_sync": sync.startswith("gps"),
            "sync": sync,
            "gateway_ip": bts_ent.get("gateway_ip"),
            "gateway_ipv6": bts_ent.get("gateway_ipv6"),
            "cells_count_fdd": self.get_cells_count_fdd(bts_ent["cells"]),
            "cells_count_tdd": self.get_cells_count_tdd(bts_ent["cells"]),
            "is_ecpri": self.is_ecpri(bts_ent["radios"]),
            "is_oran": self.is_oran(bts_ent["radios"]),
        }
        bts_ent.update(enb_ent_config)

        for cell_ent in bts_ent["cells"].values():
            cell_ent["is_fdd"] = self.is_cell_ent_fdd(cell_ent)

        self.update_radio_config(bts_ent["radios"], rmods)
        if "bbmods" in bts_ent:
            self.update_bbmod_config(bts_ent["bbmods"], bbmods_smods)
        if "smods" in bts_ent:
            self.update_smod_config(bts_ent["smods"], bbmods_smods)

    @staticmethod
    def get_bbmods_count(enb_ent):
        return len(list(enb_ent.get("bbmods", {})))

    @staticmethod
    def get_bbpool_count(enb_ent):
        return len({cell["bbpool"] for cell in enb_ent["cells"].values() if "bbpool" in cell})

    @staticmethod
    def get_smods_count(enb_ent):
        smods_count = len(list(enb_ent.get("SMODS", {}).keys()))
        if not smods_count:
            smods_ids = set()
            for bbmod_ent in enb_ent.get("bbmods", {}).values():
                if "smod" in bbmod_ent:
                    smods_ids.add(bbmod_ent["smod"])
            smods_count = len(smods_ids)

        return max(1, smods_count)

    @staticmethod
    def update_bbmod_config(bbmods, bbmods_smods):
        for bbmod_ent in bbmods.values():
            bbmod_prod_code = bbmod_ent.get("prod_code_planned", "")
            if not bbmod_prod_code:
                bbmod_ent["prod_code_planned"] = bbmods_smods["BBMODS"][bbmod_ent.get("type")]["prod_code_planned"]

    @staticmethod
    def update_radio_config(radios, rmods):
        for radio_ent in radios.values():
            radio_type = radio_ent["type"]
            radio_ent["antenna_count"] = int(rmods[radio_type]["antenna_count"])
            radio_ent["ret_count"] = int(rmods[radio_type]["ret_count"])
            if "prod_code_planned" not in radio_ent:
                radio_ent["prod_code_planned"] = rmods[radio_type]["product_code_planned"]
            if "antennas" not in radio_ent:
                radio_ent["antennas"] = {}
            if "dc_voltage" not in radio_ent["antennas"]:
                radio_ent["antennas"]["dc_voltage"] = rmods[radio_type]["dc_voltage"]
            elif len(radio_ent["antennas"]["dc_voltage"]) < len(rmods[radio_type]["dc_voltage"]):
                radio_ent["antennas"]["dc_voltage"].extend(rmods[radio_type]["dc_voltage"][len(radio_ent["antennas"]["dc_voltage"]):])

    @staticmethod
    def update_smod_config(smods, bbmods_smods):
        for smod_ent in smods.values():
            smod_prod_code = smod_ent.get("prod_code_planned", "")
            if not smod_prod_code:
                smod_ent["prod_code_planned"] = bbmods_smods["SMODS"][smod_ent.get("type")]["prod_code_planned"]


class VCUConfigurator(Configurator):

    def get_config(self, bts_ent, *_ignored):

        VCUConfiguratorExpander().expand_config(bts_ent)

        enb_ent_config = {
            "cells_count": len(bts_ent["cells"]),
            "radios_count": len(bts_ent["dus"]),
            "is_ipv4": "enb_ip" in bts_ent,
            "is_ipv6": "enb_ipv6_prefix_length" in bts_ent and "enb_ipv6" in bts_ent,
            "is_ipv6_mplane": bts_ent.get("ipv6_for_mplane", "") == "true",
            "is_ipv6_s1x2": bts_ent.get("ipv6_for_s1x2", "") == "true",
            "is_ipv6_splane": bts_ent.get("ipv6_for_splane", "") == "true",
            "cells_count_fdd": self.get_cells_count_fdd(bts_ent["cells"]),
            "cells_count_tdd": self.get_cells_count_tdd(bts_ent["cells"]),
        }
        bts_ent.update(enb_ent_config)

        for cell_ent in bts_ent["cells"].values():
            cell_ent["is_fdd"] = self.is_cell_ent_fdd(cell_ent)


class ConfiguratorExpander:

    def __init__(self) -> None:
        self.index_map = {}

    @abstractmethod
    def expand_config(self, bts_ent):
        """
        Expands declared config, if possible. It applies whenever range IDS are in use (1..10) or
        when specific keywords are provided.
        E.g. 'number_of_nrrel' in 'cells' declaration should create specific number of nrrel dicts.
        """
        pass

    def expand_expression(self, expression):
        for index_key, index_val in self.index_map.items():
            expression = expression.replace(index_key, str(index_val))
        return expression

    def expand_expression_str(self, expression):
        for index_key, index_val in self.index_map.items():
            expression = expression.replace(index_key, "'{}'".format(index_val))
        return expression

    def expand_id(self, start, stop, entry):
        if "index" in entry:
            index_key = entry["index"]
        else:
            index_key = "ID"

        ret_dict = {}
        for index in range(start, stop + 1):

            self.index_map[index_key] = index

            key_id = str(index)
            ret_dict[key_id] = {}
            for key, val in entry.items():
                if isinstance(val, dict):
                    copy_val = deepcopy(val)
                    new_val = self.expand_id_dict(copy_val)
                    ret_dict[key_id][key] = new_val
                elif isinstance(val, list):
                    copy_val = deepcopy(val)
                    new_val = self.expand_id_list(copy_val)
                    ret_dict[key_id][key] = new_val
                elif isinstance(val, str):
                    new_val = self.expand_id_scalar(val)
                    ret_dict[key_id][key] = new_val
                else:
                    ret_dict[key_id][key] = val
        return ret_dict

    def expand_id_dict(self, val):
        new_entries = {}
        for key, value in val.items():
            srch = re.search(r"(\d+)\.\.(\d+)", key)
            if srch:
                new_values = self.expand_id(int(srch.group(1)), int(srch.group(2)), value)
                new_entries[key] = new_values
        for range_entry_id, new_values in new_entries.items():
            del val[range_entry_id]
            for new_key, new_value in new_values.items():
                val[new_key] = new_value

        ret = {}
        for key, value in val.items():
            if isinstance(value, dict):
                ret[key] = self.expand_id_dict(value)
            elif isinstance(value, list):
                ret[key] = self.expand_id_list(value)
            else:
                ret[key] = self.expand_id_scalar(value)
        return ret

    def expand_id_list(self, val):
        ret = []
        for value in val:
            if isinstance(value, dict):
                ret.append(self.expand_id_dict(value))
            elif isinstance(value, list):
                ret.append(self.expand_id_list(value))
            else:
                ret.append(self.expand_id_scalar(value))
        return ret

    def expand_id_scalar(self, val):
        ret = val
        srch = re.search(r"^\$\{(.*)\}$", val)
        if srch:
            expression = self.expand_expression(srch.group(1))
            try:
                ret = eval(expression)
            except TypeError:
                expression = self.expand_expression_str(srch.group(1))
                ret = eval(expression)
        return str(ret)


class BTSConfiguratorExpander(ConfiguratorExpander):
    """
    You can declare defualt params here and add while expanding the config.
    See VCUConfiguratorExpander for the context.
    """

    def expand_config(self, bts_ent):
        for bts_val in bts_ent.values():
            if isinstance(bts_val, dict):
                self.expand_id_dict(bts_val)


class VCUConfiguratorExpander(ConfiguratorExpander):

    DEFAULT_PARAMS = {
        "VCU": {
            "MCC": "311",
            "MNC": "489",
            "TAC": "280",
            "SD": "13714341",
            "SST": "1",
        },
        "NRREL": {
            "MCC": "311",
            "MNC": "489",
            "LCR_ID": "1",
        },
        "NRADJGNB": {
            "MCC": "311",
            "MNC": "489",
        },
        "NRADJNRCELL": {
            "MCC": "311",
            "MNC": "489",
            "LCR_ID": "1",
            "EARFCN": "643000",
            "SSB_FREQUENCY": "1",
            "TYPE": "SA",
        },
        "DUS": {
            "TYPE": "ORAN",
            "GNB_DU_ID": "1",
        },
    }

    def __init__(self) -> None:
        super().__init__()
        self.sim_gnb_from_nrrels = set()

    def expand_config(self, bts_ent):
        """
        VCU allows some veryfast declaration. "DUS" can be declared without needing of explictly passing
        cells ID; One just need to pass 'init_sim_vdu_ip_addr' and then, below the DU ID 'number_of_cells'

        --- DUS ---
        dus:
            init_sim_vdu_ip_addr: '172.16.1.2'

            1:
                cell_group: [1]
                type: ORAN
                ip_addr: '172.16.1.1'

            2..16:
                number_of_cells: 17

            17..100:
                number_of_cells: 15

        --- XNLINKS ---
        XNLINKS require this specific keyword (note plural!). Besides this no NRADJ* objects can be declared;
        For reference, please see check_veryfast_xnlinks_is_possible function.

        --- CELLS ---
        CELLS can be declared 'veryfast' by omitting explicit declaration of nrrels;
        cells:
            2..1516:
                index: CELL_ID
                pci: ${CELL_ID % 1007}
                earfcn_dl: ${145800 + 20 * ((CELL_ID - 2) // 16)}
                earfcn_ul: ${139800 + 20 * ((CELL_ID - 2) // 16)}
                ch_bw: 5MHz
                scs: 15 KHz
                freq_band: 85

                number_of_nrrels: 10
                init_sim_gnb_id_for_nrrel: 1101
        """

        is_veryfast_dus_declaration_possible = "dus" in bts_ent and "init_sim_vdu_ip_addr" in bts_ent["dus"]
        is_veryfast_xnlinks_declaration_possible = self.check_veryfast_xnlinks_is_possible(bts_ent)

        if is_veryfast_dus_declaration_possible:
            self.expand_veryfast_dus_declaration(bts_ent)

        if is_veryfast_xnlinks_declaration_possible:
            self.expand_veryfast_xnlinks_declaration(bts_ent)

        for bts_key, bts_val in bts_ent.items():
            if isinstance(bts_val, dict):
                if bts_key == "cells":
                    self.expand_cells_declaration(bts_val)
                    continue
                self.expand_id_dict(bts_val)

        self.add_missing_vcu_keys(bts_ent)

    def add_missing_vcu_keys(self, bts_ent):
        for key, val in self.DEFAULT_PARAMS["VCU"].items():
            if key.lower() not in bts_ent:
                bts_ent[key.lower()] = val

    def expand_cells_declaration(self, cells_ent):
        self.expand_id_dict(cells_ent)

        for cell_ent in cells_ent.values():

            if "number_of_nrrels" in cell_ent and "init_sim_gnb_id_for_nrrel" in cell_ent:

                number_of_nrrels = int(cell_ent.pop("number_of_nrrels"))
                init_sim_gnb_id_for_nrrel = cell_ent.pop("init_sim_gnb_id_for_nrrel")
                sim_gnb_id_counter = count(int(init_sim_gnb_id_for_nrrel))

                nrrels = {}
                for index in range(1, number_of_nrrels + 1):
                    sim_gnb_id = next(sim_gnb_id_counter)
                    self.sim_gnb_from_nrrels.add(str(sim_gnb_id))
                    nrrels[str(index)] = {
                        "mcc": self.DEFAULT_PARAMS["NRREL"]["MCC"],
                        "mnc": self.DEFAULT_PARAMS["NRREL"]["MNC"],
                        "lcr_id": self.DEFAULT_PARAMS["NRREL"]["LCR_ID"],
                        "gnb_id": str(sim_gnb_id),
                    }
                cell_ent["nrrel"] = nrrels

    def expand_veryfast_dus_declaration(self, bts_ent):
        dus_ent = bts_ent["dus"]

        init_sim_vdu_ip_addr = dus_ent.pop("init_sim_vdu_ip_addr")
        ipv4_generator = count(IPv4Address(init_sim_vdu_ip_addr))

        sorted_keys = sorted(dus_ent, key=self.extract_first_number)

        new_dus_ent = {}
        last_real_vdu_key = ""
        for key in sorted_keys:
            if "number_of_cells" in dus_ent[key]:
                break
            new_dus_ent[key] = dus_ent[key]
            last_real_vdu_key = key

        cell_grp_generator = count(int(dus_ent[last_real_vdu_key]["cell_group"][-1]) + 1)

        sim_vdu_keys = sorted_keys[sorted_keys.index(last_real_vdu_key) + 1:]

        for key in sim_vdu_keys:

            val = dus_ent.pop(key)

            val.pop("ip_addr", None)
            val.pop("cell_group", None)

            number_of_cells = int(val.pop("number_of_cells", 1))

            expanded_keys = self.expand_range(key)
            for du_id in expanded_keys:
                str_du_id = str(du_id)
                new_dus_ent[str_du_id] = deepcopy(val)

                if "type" not in val:
                    new_dus_ent[str_du_id]["type"] = self.DEFAULT_PARAMS["DUS"]["TYPE"]

                cell_grp = [str(next(cell_grp_generator)) for _ in range(number_of_cells)]
                ip_addr = str(next(ipv4_generator))

                new_dus_ent[str_du_id]["cell_group"] = cell_grp
                new_dus_ent[str_du_id]["ip_addr"] = ip_addr

        bts_ent["dus"] = new_dus_ent

    def expand_veryfast_xnlinks_declaration(self, bts_ent):

        xnlinks_ent = bts_ent.pop("xnlinks")

        init_xnlink_ip_addr = xnlinks_ent.pop("init_xnlink_ip_addr")
        ipv4_generator = count(IPv4Address(init_xnlink_ip_addr))

        init_sim_gnb_id = xnlinks_ent.pop("init_sim_gnb_id")
        sim_gnb_id_generator = count(int(init_sim_gnb_id))

        nradjnrcell_id_generator = count(1)
        xnlink = {}
        nradjgnb = {}
        nradjnrcell = {}

        sorted_keys = sorted(xnlinks_ent, key=self.extract_first_number)
        declared_gnbs = {}
        for key in sorted_keys:
            expanded_keys = self.expand_range(key)
            number_of_nradjnrcells = int(xnlinks_ent[key]["number_of_cells_per_gnb"])
            for index in expanded_keys:
                xnlink[str(index)] = {"ip_addr": str(next(ipv4_generator))}
                gnb_id = next(sim_gnb_id_generator)
                nradjgnb[str(index)] = {
                    "gnb_id": str(gnb_id),
                    "mcc": self.DEFAULT_PARAMS["NRADJGNB"]["MCC"],
                    "mnc": self.DEFAULT_PARAMS["NRADJGNB"]["MNC"],
                }
                declared_gnbs[str(gnb_id)] = index

                for _ in range(number_of_nradjnrcells):
                    cell_index = next(nradjnrcell_id_generator)

                    nradjnrcell[str(cell_index)] = {
                        "gnb_id": str(gnb_id),
                        "pci": str(cell_index),
                        "type": self.DEFAULT_PARAMS["NRADJNRCELL"]["TYPE"],
                        "mcc": self.DEFAULT_PARAMS["NRADJNRCELL"]["MCC"],
                        "mnc": self.DEFAULT_PARAMS["NRADJNRCELL"]["MNC"],
                        "lcr_id": self.DEFAULT_PARAMS["NRADJNRCELL"]["LCR_ID"],
                        "earfcn": self.DEFAULT_PARAMS["NRADJNRCELL"]["EARFCN"],
                        "ssb_frequency": self.DEFAULT_PARAMS["NRADJNRCELL"]["SSB_FREQUENCY"],
                    }

        missing_keys = self.sim_gnb_from_nrrels - declared_gnbs.keys()
        for key in missing_keys:
            index += 1
            nradjgnb[str(index)] = {"gnb_id": key, "mcc": self.DEFAULT_PARAMS["NRADJGNB"]["MCC"], "mnc": self.DEFAULT_PARAMS["NRADJGNB"]["MCC"]}
            cell_index = next(nradjnrcell_id_generator)
            nradjnrcell[str(cell_index)] = {
                "pci": str(cell_index),
                "gnb_id": str(key),
                "type": self.DEFAULT_PARAMS["NRADJNRCELL"]["TYPE"],
                "mcc": self.DEFAULT_PARAMS["NRADJNRCELL"]["MCC"],
                "mnc": self.DEFAULT_PARAMS["NRADJNRCELL"]["MNC"],
                "lcr_id": self.DEFAULT_PARAMS["NRADJNRCELL"]["LCR_ID"],
                "earfcn": self.DEFAULT_PARAMS["NRADJNRCELL"]["EARFCN"],
                "ssb_frequency": self.DEFAULT_PARAMS["NRADJNRCELL"]["SSB_FREQUENCY"],
            }

        bts_ent.update(
            {
                "xnlink": xnlink,
                "nradjgnb": nradjgnb,
                "nradjnrcell": nradjnrcell,
            }
        )

    @staticmethod
    def check_veryfast_xnlinks_is_possible(bts_ent):

        if "xnlinks" not in bts_ent:
            return False

        if "xnlink" in bts_ent:
            raise Exception("Declartion of XNLINKS cannot be mixed with 'XNLINK' and 'XNLINKS' keyword.")

        if "nradjgnb" in bts_ent:
            raise Exception("Declaration of NRADJGNB is handled by respective XNLINKS entities. 1 NRADJGNB, PER 1 XNLINK.")

        if "nradjcell" in bts_ent:
            raise Exception("Declaration of NRADJCELL is handled by respective XNLINKS entities and 'number_of_cells_per_gnb' key.")

        xnlinks = bts_ent["xnlinks"]
        if "init_xnlink_ip_addr" not in xnlinks:
            raise Exception("Veryfast XNLINKS declaration requires initial IP address (ipv4 format).")

        if "init_sim_gnb_id" not in xnlinks:
            raise Exception("Veryfast XNLINKS declaration requires initial GNB ID declaration.")

        return True

    @staticmethod
    def extract_first_number(item):
        """Extracts the first number from an item (int or range)."""
        if isinstance(item, int):
            return item
        match = re.match(r"(\d+)", item)
        return int(match.group(1)) if match else float("inf")

    @staticmethod
    def expand_range(item):
        """Expands a range like '2..12' into a list of numbers."""
        if isinstance(item, int):
            return [item]

        match = re.match(r"(\d+)\.\.(\d+)", item)
        if match:
            start, end = map(int, match.groups())
            return list(range(start, end + 1))
        return [int(item)]

    def sort_elements(self, elements):
        """Sorts a list with individual numbers and ranges."""
        expanded = []
        for elem in elements:
            expanded.extend(self.expand_range(elem))
        return sorted(expanded)
